export const WOD_DATABASE_BY_NAME: Map<string, NamedWorkout> = new Map(
  WOD_DATABASE.map((w) => [w.name.toLowerCase(), w])
);

export const WOD_CATEGORY_LABELS: Record<WodCategory, string> = {
  girls: "The Girls",
  hero: "Hero WOD",
  open: "CrossFit Open",
  other: "Named benchmark",
};

/** A one-line, ready-to-drop-into-notes description of a known WOD. */
export function formatWodDetails(workout: NamedWorkout): string {
  return workout.loads ? `${workout.description}. Load: ${workout.loads}.` : `${workout.description}.`;
}
